import { useState, useEffect } from 'react';
import ResultView from './ResultView';

const API = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');

const gradeColor = g => g==='A+'||g==='A'?'#16a34a':g==='F'?'#dc2626':g==='B'?'#2563eb':g==='C'?'#d97706':'#6b7280';
const gradeBg    = g => g==='A+'||g==='A'?'#dcfce7':g==='F'?'#fee2e2':g==='B'?'#dbeafe':g==='C'?'#fef3c7':'#f3f4f6';
const dCol       = d => d==='Easy'?'#16a34a':d==='Hard'?'#dc2626':'#d97706';
const dBg        = d => d==='Easy'?'#dcfce7':d==='Hard'?'#fee2e2':'#fef3c7';

export default function MyResults({ store }) {
  const [viewSubId,  setViewSubId]  = useState(null);
  const [examResults,setExamResults]= useState([]);
  const [practiceResults, setPracticeResults] = useState([]);
  const [loading,    setLoading]    = useState(true);
  const [search,     setSearch]     = useState('');
  const [tab,        setTab]        = useState('exams');
  const [expandedId, setExpandedId] = useState(null); // for practice detail expand

  useEffect(() => { loadExams(); loadPractice(); }, []);

  const loadExams = async () => {
    try {
      const sid  = store.getStudentSid();
      const subs = await fetch(`${API}/submissions/student/${sid}`, { headers:{ Authorization:`Bearer ${getToken()}` } }).then(r=>r.json());
      const subsArr = Array.isArray(subs) ? subs : [];
      const enriched = await Promise.all(subsArr.map(async s => {
        const [result, examsData] = await Promise.all([
          fetch(`${API}/submissions/result/${s.submission_id}`, { headers:{ Authorization:`Bearer ${getToken()}` } }).then(r=>r.json()).catch(()=>null),
          fetch(`${API}/exams`, { headers:{ Authorization:`Bearer ${getToken()}` } }).then(r=>r.json()).catch(()=>[]),
        ]);
        const exam = Array.isArray(examsData) ? examsData.find(e=>e.exam_id===s.exam_id) : null;
        return { sub:s, result, exam };
      }));
      setExamResults(enriched.filter(x=>x.result&&x.exam).reverse());
    } catch(e) { console.error(e); }
    finally { setLoading(false); }
  };

  const loadPractice = () => {
    try {
      const stored = JSON.parse(localStorage.getItem('practice_results')||'[]');
      setPracticeResults(stored);
    } catch { setPracticeResults([]); }
  };

  if (viewSubId) return <ResultView submissionId={viewSubId} store={store} onBack={() => setViewSubId(null)}/>;

  const filteredExams    = examResults.filter(r => r.exam?.title?.toLowerCase().includes(search.toLowerCase()));
  const filteredPractice = practiceResults.filter(p =>
    p.subject?.toLowerCase().includes(search.toLowerCase()) ||
    p.mode?.toLowerCase().includes(search.toLowerCase())
  );

  const gpa = examResults.length ? (examResults.reduce((a,r) => {
    const pts = {'A+':4,'A':4,'B':3,'C':2,'D':1,'F':0}[r.result?.grade]||0;
    return a + pts;
  }, 0) / examResults.length).toFixed(2) : '—';
  const successRate = examResults.length ? Math.round(examResults.filter(r=>r.result?.grade!=='F').length/examResults.length*100) : 0;

  return (
    <div className="fade-up">
      <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:26, color:'#0f0f1a', marginBottom:4 }}>Academic Performance History</h1>
      <p style={{ fontSize:13, color:'#6b7280', marginBottom:20 }}>Review your past exam results and practice sessions.</p>

      {/* Stat cards — exam only */}
      <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12, marginBottom:20 }}>
        {[
          { label:'Current GPA',      value:gpa,                sub:'+0.15 this month',    icon:'🏅', color:'accent' },
          { label:'Exams Completed',  value:examResults.length,  sub:'Official exams only', icon:'📄', color:'blue'   },
          { label:'Success Rate',     value:`${successRate}%`,   sub:'Grade D or above',    icon:'📈', color:'green'  },
        ].map((s,i) => (
          <div key={i} className={`stat-card ${s.color}`}>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
              <div>
                <div className="stat-label">{s.label}</div>
                <div className="stat-value" style={{ fontSize:26 }}>{s.value}</div>
                <div className="stat-sub">{s.sub}</div>
              </div>
              <span style={{ fontSize:20, opacity:.25 }}>{s.icon}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Tabs + search */}
      <div style={{ display:'flex', gap:12, marginBottom:16, alignItems:'center' }}>
        <div style={{ display:'flex', gap:1, background:'#f3f4f6', padding:3, borderRadius:9, border:'1px solid #e5e7eb' }}>
          {[
            { key:'exams',    label:`Exams (${examResults.length})` },
            { key:'practice', label:`Practice (${practiceResults.length})` },
          ].map(t => (
            <button key={t.key} onClick={()=>{ setTab(t.key); setSearch(''); setExpandedId(null); }}
              style={{ padding:'7px 18px', borderRadius:7, border:'none', cursor:'pointer', fontSize:13, fontWeight:600, transition:'all .15s',
                background:tab===t.key?'#fff':'transparent',
                color:tab===t.key?'#0f0f1a':'#6b7280',
                boxShadow:tab===t.key?'0 1px 4px rgba(0,0,0,.08)':'' }}>
              {t.label}
            </button>
          ))}
        </div>
        <div style={{ flex:1, position:'relative' }}>
          <span style={{ position:'absolute', left:12, top:'50%', transform:'translateY(-50%)', color:'#9ca3af', fontSize:14 }}>🔍</span>
          <input className="form-input" style={{ paddingLeft:38 }}
            placeholder={tab==='exams'?'Search by exam title...':'Search by subject or mode...'}
            value={search} onChange={e=>setSearch(e.target.value)}/>
        </div>
      </div>

      {/* ── EXAM RESULTS ── */}
      {tab === 'exams' && (
        loading ? (
          <div style={{ display:'flex', alignItems:'center', gap:12, padding:40, justifyContent:'center' }}>
            <div className="spinner" style={{width:24,height:24}}/><span style={{color:'#6b7280'}}>Loading results...</span>
          </div>
        ) : filteredExams.length === 0 ? (
          <div className="empty-state"><div className="empty-icon">🏆</div><div className="empty-title">No exam results yet</div><div className="empty-sub">Complete an exam to see your results here</div></div>
        ) : (
          <div style={{ display:'flex', flexDirection:'column', gap:1, background:'#fff', borderRadius:14, border:'1px solid #e8e8f0', overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.06)' }}>
            {filteredExams.map(({ sub, result, exam }, i) => {
              const pct = exam ? Math.round(Number(result.total_score)/Number(exam.total_marks)*100) : 0;
              const g   = result.grade || 'F';
              const gc  = gradeColor(g);
              const isCheated = result.cheating_detected;
              return (
                <div key={sub.submission_id}
                  style={{ display:'flex', alignItems:'center', gap:16, padding:'16px 20px', borderBottom:i<filteredExams.length-1?'1px solid #f3f4f6':'none', transition:'background .15s' }}
                  onMouseEnter={e=>e.currentTarget.style.background='#f8f8fc'}
                  onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                  <div style={{ width:44, height:44, borderRadius:10, background:gradeBg(g), display:'flex', alignItems:'center', justifyContent:'center', fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:16, color:gc, flexShrink:0, border:`1px solid ${gc}22` }}>{g}</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:3 }}>
                      <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a' }}>{exam.title}</span>
                      {isCheated && <span style={{ padding:'2px 8px', borderRadius:4, background:'#fee2e2', color:'#dc2626', fontSize:10, fontWeight:700 }}>Integrity Violation</span>}
                    </div>
                    <div style={{ display:'flex', gap:14, fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', alignItems:'center' }}>
                      <span>📅 {sub.submit_time?new Date(sub.submit_time).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'-'}</span>
                      <span>📊 Score: {Number(result.total_score).toFixed(0)}/{exam.total_marks}</span>
                    </div>
                  </div>
                  <div style={{ width:160, flexShrink:0 }}>
                    <div style={{ display:'flex', justifyContent:'space-between', fontSize:10, color:'#9ca3af', marginBottom:4, fontFamily:'JetBrains Mono,monospace' }}>
                      <span>SCORE</span><span style={{ color:gc, fontWeight:700 }}>{pct}%</span>
                    </div>
                    <div style={{ height:5, background:'#f3f4f6', borderRadius:3, overflow:'hidden' }}>
                      <div style={{ height:'100%', width:`${pct}%`, background:`linear-gradient(90deg,${gc}88,${gc})`, borderRadius:3 }}/>
                    </div>
                  </div>
                  <div style={{ display:'flex', gap:6, flexShrink:0 }}>
                    <button className="btn btn-primary btn-sm" onClick={() => setViewSubId(sub.submission_id)} style={{ fontSize:12 }}>
                      View Details →
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )
      )}

      {/* ── PRACTICE RESULTS ── */}
      {tab === 'practice' && (
        filteredPractice.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">🧠</div>
            <div className="empty-title">No practice sessions yet</div>
            <div className="empty-sub">Go to Practice tab and complete a session to see history here</div>
          </div>
        ) : (
          <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
            {/* Note */}
            <div style={{ background:'#f8f9fa', border:'1px solid #e8e8f0', borderRadius:10, padding:'10px 16px', fontSize:12, color:'#6b7280', display:'flex', alignItems:'center', gap:8 }}>
              <span>ℹ</span> Practice sessions are not included in your GPA or leaderboard.
            </div>

            {filteredPractice.map((p, i) => {
              const gc  = gradeColor(p.grade);
              const gbg = gradeBg(p.grade);
              const modeColor = p.mode==='adaptive'?'#7c3aed':'#16a34a';
              const modeBg    = p.mode==='adaptive'?'#ede9fe':'#dcfce7';
              const isExpanded = expandedId === p.id;
              const a = p.analysis;

              return (
                <div key={p.id} style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
                  {/* Main row */}
                  <div style={{ display:'flex', alignItems:'center', gap:16, padding:'16px 20px' }}>
                    {/* Grade */}
                    <div style={{ width:48, height:48, borderRadius:12, background:gbg, display:'flex', alignItems:'center', justifyContent:'center', fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:18, color:gc, flexShrink:0, border:`1px solid ${gc}22` }}>
                      {p.grade}
                    </div>
                    {/* Info */}
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:5, flexWrap:'wrap' }}>
                        <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a' }}>{p.subject}</span>
                        <span style={{ padding:'2px 10px', borderRadius:20, background:modeBg, color:modeColor, fontSize:10, fontWeight:700, fontFamily:'JetBrains Mono,monospace' }}>
                          {p.mode==='adaptive'?'Adaptive':'Standard'} · {p.difficulty}
                        </span>
                        {p.level && <span style={{ padding:'2px 10px', borderRadius:20, background:'#f3f4f6', color:'#6b7280', fontSize:10, fontWeight:600 }}>{p.level}</span>}
                      </div>
                      <div style={{ display:'flex', gap:16, fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', alignItems:'center' }}>
                        <span>📅 {new Date(p.date).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span>
                        <span>✓ {p.correct}/{p.total_questions} correct</span>
                        {p.mode==='adaptive' && <span>ELO {p.elo}</span>}
                      </div>
                    </div>
                    {/* Score bar */}
                    <div style={{ width:150, flexShrink:0 }}>
                      <div style={{ display:'flex', justifyContent:'space-between', fontSize:10, color:'#9ca3af', marginBottom:4, fontFamily:'JetBrains Mono,monospace' }}>
                        <span>SCORE</span><span style={{ color:gc, fontWeight:700 }}>{p.score_pct}%</span>
                      </div>
                      <div style={{ height:6, background:'#f3f4f6', borderRadius:3, overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${p.score_pct}%`, background:`linear-gradient(90deg,${gc}88,${gc})`, borderRadius:3 }}/>
                      </div>
                    </div>
                    {/* Toggle button */}
                    {a && (
                      <button onClick={() => setExpandedId(isExpanded ? null : p.id)}
                        style={{ padding:'7px 16px', background:isExpanded?'#ede9fe':'#f3f4f6', color:isExpanded?'#7c3aed':'#374151', border:`1px solid ${isExpanded?'#ddd6fe':'#e5e7eb'}`, borderRadius:8, fontSize:12, fontWeight:600, cursor:'pointer', flexShrink:0, transition:'all .15s' }}>
                        {isExpanded ? 'Hide ▴' : 'Details ▾'}
                      </button>
                    )}
                  </div>

                  {/* Expanded analysis */}
                  {isExpanded && a && (
                    <div style={{ borderTop:'1px solid #f3f4f6', padding:'16px 20px', background:'#f8f8fc' }}>
                      {/* Overall feedback */}
                      <div style={{ fontSize:13, color:'#374151', lineHeight:1.7, marginBottom:16, padding:'12px 16px', background:'#fff', borderRadius:9, border:'1px solid #e8e8f0' }}>
                        {a.overall_feedback}
                      </div>

                      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:12, marginBottom:14 }}>
                        {/* Strengths */}
                        {a.strong_topics?.length > 0 && (
                          <div style={{ background:'#f0fdf4', border:'1px solid #bbf7d0', borderRadius:10, padding:'12px 14px' }}>
                            <div style={{ fontSize:10, fontWeight:700, color:'#16a34a', fontFamily:'JetBrains Mono,monospace', marginBottom:8, letterSpacing:1 }}>💪 STRENGTHS</div>
                            {a.strong_topics.map((t,j) => (
                              <div key={j} style={{ fontSize:12, color:'#166534', marginBottom:4, display:'flex', gap:6 }}>
                                <span style={{ color:'#16a34a', flexShrink:0 }}>✓</span>{t}
                              </div>
                            ))}
                          </div>
                        )}
                        {/* Weak topics */}
                        {a.weak_topics?.length > 0 && (
                          <div style={{ background:'#fef2f2', border:'1px solid #fecaca', borderRadius:10, padding:'12px 14px' }}>
                            <div style={{ fontSize:10, fontWeight:700, color:'#dc2626', fontFamily:'JetBrains Mono,monospace', marginBottom:8, letterSpacing:1 }}>📚 NEEDS WORK</div>
                            {a.weak_topics.map((t,j) => (
                              <div key={j} style={{ fontSize:12, color:'#991b1b', marginBottom:4, display:'flex', gap:6 }}>
                                <span style={{ color:'#dc2626', flexShrink:0 }}>→</span>{t}
                              </div>
                            ))}
                          </div>
                        )}
                        {/* Readiness */}
                        <div style={{ background:'#eff6ff', border:'1px solid #bfdbfe', borderRadius:10, padding:'12px 14px' }}>
                          <div style={{ fontSize:10, fontWeight:700, color:'#2563eb', fontFamily:'JetBrains Mono,monospace', marginBottom:8, letterSpacing:1 }}>🎯 READINESS</div>
                          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:14, color:'#1d4ed8', marginBottom:6 }}>{a.predicted_exam_readiness}</div>
                          {a.next_steps && <div style={{ fontSize:11, color:'#1e40af', lineHeight:1.5 }}>{a.next_steps}</div>}
                        </div>
                      </div>

                      {/* Tips */}
                      {a.improvement_tips?.length > 0 && (
                        <div style={{ background:'#fffbeb', border:'1px solid #fde68a', borderRadius:10, padding:'12px 14px' }}>
                          <div style={{ fontSize:10, fontWeight:700, color:'#d97706', fontFamily:'JetBrains Mono,monospace', marginBottom:8, letterSpacing:1 }}>💡 IMPROVEMENT TIPS</div>
                          {a.improvement_tips.map((t,j) => (
                            <div key={j} style={{ fontSize:12, color:'#78350f', marginBottom:5, display:'flex', gap:8, lineHeight:1.55 }}>
                              <span style={{ color:'#d97706', flexShrink:0, fontWeight:700 }}>{j+1}.</span>{t}
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )
      )}
    </div>
  );
}
